import os

def pin_tip(path):
    im = Image.open(path).convert("L")
    w,h=im.size
    pix=im.load()
    # large component of v<36
    vis=[[0]*w for _ in range(h)]
    # find a seed in the big dark area - top center
    # flood from (w//2, 40) if dark else search
    seed=None
    for y in range(h):
        for x in range(w):
            if pix[x,y]<36:
                seed=(x,y); break
        if seed: break
    stack=[seed]; vis[seed[1]][seed[0]]=1
    miny=seed[1]; maxy=seed[1]
    bottom_pts=[]
    count=0
    while stack:
        x,y=stack.pop(); count+=1
        if y>maxy:
            maxy=y; bottom_pts=[(x,y)]
        elif y==maxy:
            bottom_pts.append((x,y))
        if y<miny: miny=y
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<w and 0<=ny<h and not vis[ny][nx] and pix[nx,ny]<36:
                vis[ny][nx]=1
                stack.append((nx,ny))
    xs=[p[0] for p in bottom_pts]
    return count, (sum(xs)/len(xs), maxy), (min(xs), max(xs)), miny

for fn in sorted(os.listdir("/home/robot/captures")):
    if fn.startswith("wrist"):
        print(fn, pin_tip(f"/home/robot/captures/{fn}"))

