    stack=[seed]; vis[seed[1]][seed[0]]=1
    while stack:
        x,y=stack.pop()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<w and 0<=ny<h and not vis[ny][nx] and pix[nx,ny]<40:
                vis[ny][nx]=1
                stack.append((nx,ny))
