# also find circular dark blobs that are bores: v<40, small, not touching the big pin
def bores(path):
    im = Image.open(path).convert("L")
    w,h=im.size
    pix=im.load()
    vis=[[0]*w for _ in range(h)]
    # mark pin
    seed=None
    for y in range(h):
        for x in range(w):
            if pix[x,y]<36:
                seed=(x,y); break
        if seed: break
    stack=[seed]; vis[seed[1]][seed[0]]=1
    while stack:
        x,y=stack.pop()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<w and 0<=ny<h and not vis[ny][nx] and pix[nx,ny]<40:
                vis[ny][nx]=1
                stack.append((nx,ny))
    comps=[]
    for y in range(h):
        for x in range(w):
            if vis[y][x] or pix[x,y]>=45:
                continue
            stack=[(x,y)]; vis[y][x]=1; pts=[]
            while stack:
                cx,cy=stack.pop(); pts.append((cx,cy))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=cx+dx,cy+dy
                    if 0<=nx<w and 0<=ny<h and not vis[ny][nx] and pix[nx,ny]<45:
                        vis[ny][nx]=1; stack.append((nx,ny))
            if len(pts)<30: continue
            xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
            bw=max(xs)-min(xs); bh=max(ys)-min(ys)
            comps.append((len(pts), sum(xs)/len(xs), sum(ys)/len(ys), bw, bh, min(xs),min(ys),max(xs),max(ys)))
    return comps

